// Check each user's platform connections for staleness
const now = new Date();
const twentyFourHoursMs = 24 * 60 * 60 * 1000;
const seventyTwoHoursMs = 72 * 60 * 60 * 1000;
const results = [];

const items = Array.isArray($input.all()) ? $input.all() : [$input.first()];

for (const item of items) {
  const data = item.json;
  const users = Array.isArray(data) ? data : (data.data ? data.data : [data]);

  for (const user of users) {
    const platforms = user.platforms || user.platformConnections || [];

    for (const platform of platforms) {
      const lastSync = platform.lastSyncAt ? new Date(platform.lastSyncAt) : null;

      if (!lastSync) {
        results.push({
          json: {
            userId: user.id || user._id,
            platform: platform.name || platform.platform,
            status: 'broken',
            reason: 'Never synced',
            lastSyncAt: null
          }
        });
        continue;
      }

      const timeSinceSync = now.getTime() - lastSync.getTime();

      if (timeSinceSync > seventyTwoHoursMs) {
        results.push({
          json: {
            userId: user.id || user._id,
            platform: platform.name || platform.platform,
            status: 'broken',
            reason: 'No sync for 72+ hours',
            lastSyncAt: platform.lastSyncAt,
            hoursSinceSync: Math.floor(timeSinceSync / (60 * 60 * 1000))
          }
        });
      } else if (timeSinceSync > twentyFourHoursMs) {
        results.push({
          json: {
            userId: user.id || user._id,
            platform: platform.name || platform.platform,
            status: 'stale',
            reason: 'No sync for 24+ hours',
            lastSyncAt: platform.lastSyncAt,
            hoursSinceSync: Math.floor(timeSinceSync / (60 * 60 * 1000))
          }
        });
      }
    }
  }
}

if (results.length === 0) {
  return [{ json: { allHealthy: true, message: 'All platform connections are healthy', checkedAt: now.toISOString() } }];
}

return results;
